INSERT INTO feature VALUES('row-polymorphism','effects','Row-polymorphic effects','effect-rows','implemented','uncommon','mainstream languages','A returner''s row stays open through a row variable, an implicit of the kind `Row`, written `-F [I, … | r] A` or `-F [r] A`: an omitted `r` is solved at each call by the row equation, so one definition is used under every row holding its interfaces, and a handler takes `[I | r]` to `[r]`, forwarding the rest. A call whose row nothing reads, or two open rows each holding an interface the other lacks, is refused naming the slot `f[.r = …]`.','core-term core-unify core-checker core-incremental surface-grammar surface-lowering surface-pretty','corpus/model/control/row-variable.gandr corpus/pathological/control/row-variable.gandr','corpus/model/control/row-variable.gandr','#2319');
